use hog4pilot::{recognition::*,project::Store,venue::Venue};
fn profile()->Fingerprint{Fingerprint{id:"test-a".into(),revision:1,manufacturer:"OEM A".into(),model:"Synthetic dimmer".into(),mode:"1ch".into(),source:"Synthetic test, not hardware".into(),channels:vec![Channel{offset:1,fine_of:None,neutral:Some(0),ranges:vec![Range{min:0,max:255,function:Function::Intensity,semantics:"linear intensity 0 to 100 percent".into()}]}]}}
#[test]fn manufacturer_independent(){let a=profile();let mut b=a.clone();b.id="other-brand".into();b.manufacturer="OEM B".into();assert_eq!(compare(&a,&b).unwrap().verdict,Verdict::StructuralMatch);}
#[test]fn equal_count_not_compatibility(){let a=profile();let mut b=a.clone();b.channels[0].ranges[0].function=Function::Reset;let r=compare(&a,&b).unwrap();assert_eq!(r.verdict,Verdict::Incompatible);assert!(r.hazardous);}
#[test]fn missing_data_never_matches(){let mut a=profile();a.channels[0].neutral=None;assert_eq!(compare(&a,&a).unwrap().verdict,Verdict::InsufficientData);a.channels[0].ranges[0].max=200;assert!(a.missing().len()>1);}
#[test]fn malformed_ranges_and_fine(){let mut a=profile();let duplicate=a.channels[0].ranges[0].clone();a.channels[0].ranges.push(duplicate);assert!(a.validate().is_err());let mut a=profile();a.channels[0].fine_of=Some(1);assert!(a.validate().is_err());}
#[test]fn neutral_and_range_semantics_matter(){let a=profile();let mut b=a.clone();b.channels[0].neutral=Some(1);assert_eq!(compare(&a,&b).unwrap().verdict,Verdict::Incompatible);b=a.clone();b.channels[0].ranges[0].semantics="inverted intensity".into();assert_eq!(compare(&a,&b).unwrap().verdict,Verdict::Incompatible);}
#[test]fn immutable_library_and_passive_evidence(){let store=Store::open(std::path::Path::new(":memory:")).unwrap();let a=profile();store.import_fingerprint(&a).unwrap();assert!(store.import_fingerprint(&a).is_err());assert_eq!(store.search_fingerprint(&a).unwrap().len(),1);let v=Venue::import_patch("id,universe,address,channels,kind\nOEM,0,1,1,unknown").unwrap();store.save_venue(&v).unwrap();store.note_candidate("OEM",&a.id,1,"Manual p.12").unwrap();assert!(!store.load_venue().unwrap().unwrap().fixtures[0].verified);assert!(store.note_candidate("missing",&a.id,1,"note").is_err());}
